#include <stdio.h>

void increment(int *value) {   // pointer parameter lets this modify the CALLER's variable
    (*value)++;
}

int main() {
    int arr[3] = {10, 20, 30};
    int *p = arr;                          // decays to &arr[0]
    printf("%d %d\n", arr[1], *(p + 1));    // 20 20 — equivalent access

    int x = 5;
    increment(&x);
    printf("%d\n", x);                       // 6 — modified through the pointer

    int **pp = &p;                          // pointer to a pointer
    printf("%d\n", **pp);                    // dereference twice: 10
    return 0;
}
